@torch.no_grad()
def sample(model, shape, steps):
    z = torch.randn(shape)              # t = 0: pure noise
    h = 1.0 / steps
    for i in range(steps):
        t = torch.full((shape[0], 1), i * h)
        z = z + h * model(z, t)         # one Euler step = one network call
    return z                            # t = 1: sample
